const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const notes=new URLSearchParams(location.search).has('notes');
let state={index:0,total:0,elapsed:0,running:false,auto:false,stamp:Date.now()},last=Date.now(),lastSeen=0;
const clock=ms=>{const s=Math.floor(Math.max(0,ms)/1000);return `${String(Math.floor(s/60)).padStart(2,'0')}:${String(s%60).padStart(2,'0')}`};
function render(){const s=slides[state.index];$('#counter').textContent=`${String(state.index+1).padStart(2,'0')} / 18`;$('#section').textContent=s.section;$('#prev').disabled=state.index===0;$('#next').disabled=state.index===17;$('#progress').style.width=`${(state.index+1)/18*100}%`;
if(notes){$('#script').innerHTML=`<span class="eyebrow">${esc(s.section)} · Página ${state.index+1} de ${slides.length}</span><h1>${esc(s.title)}</h1><p class="sub">En pantalla: ${esc(s.sub)}</p><div>${esc(s.script)}</div><p class="sub">Sigue: ${esc(slides[state.index+1]?.title||'Fin de la charla')}</p>`;$('#index').innerHTML=slides.map((x,i)=>`<button class="${i===state.index?'active':''}" data-go="${i}" title="${esc(x.title)}">${i+1}</button>`).join('');return}
document.body.dataset.kind=s.kind;document.body.dataset.slide=state.index;
const wide=['chain','broken','metrics','flow'].includes(s.kind);
let content='';
if(s.kind==='hero')content=`<div class="opening-line">Los agentes han despertado.</div><h1>Esta noche<br>le damos<br><em>billetera.</em></h1><p class="lead">${esc(s.sub)}</p><span class="ticket">UNA HISTORIA DE AGENTES & BLOCKCHAIN</span>`;
else {
 const heading=`<h1>${esc(s.title)}</h1><p class="lead">${esc(s.sub)}</p>`;
 let visual='';
 if(s.kind==='code')visual=`<div class="spellbook"><div class="book-label">GRIMORIO DEL DESARROLLADOR · ${state.index===14?'PSEUDOCÓDIGO':'NOTAS DE LABORATORIO'}</div><pre>${s.items.map((x,i)=>`<span><b>${String(i+1).padStart(2,'0')}</b><code>${esc(x)||' '}</code></span>`).join('')}</pre></div>`;
 else if(s.kind==='table')visual=`<div class="ledger"><table>${s.items.map((x,i)=>`<tr>${x.split('|').map(v=>i===0?`<th>${esc(v)}</th>`:`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</table></div>`;
 else if(s.kind==='network')visual=`<div class="coven">${s.items.slice(0,4).map((x,i)=>`<span class="sigil"><i>${['✦','☾','✧','☆'][i]}</i>${esc(x)}</span>`).join('')}</div><p class="aside-note">${esc(s.items[4])}</p>`;
 else if(s.kind==='closing')visual=`<div class="resource-scroll">${s.items.map(x=>`<a href="https://${x}" target="_blank" rel="noopener">${esc(x)} <span>↗</span></a>`).join('')}</div><p class="aside-note">Stellar es una marca de Stellar Development Foundation. Presentación comunitaria independiente.</p>`;
 else visual=`<div class="${s.kind==='flow'?'ritual':s.kind==='stack'?'incantation':'graveyard'}">${s.items.map((x,i)=>{const [a,b]=x.split('|');return `<div class="paper-piece"><span class="piece-rune">${s.kind==='flow'?String(i+1).padStart(2,'0'):['☾','✦','✧','☆'][i%4]}</span><strong>${esc(s.kind==='flow'?a.replace(/^\d+\s*·\s*/, ''):a)}</strong><p>${esc(b||'')}</p></div>`}).join('')}</div>`;
 content=heading+`<div class="visual">${visual}</div>`+(state.index===9?'<p class="aside-note">Mínimo clásico sin congestión. Soroban añade tarifas por recursos.</p>':'');
}
$('#stage').innerHTML=`<article class="slide ${wide?'composition-wide':'composition-split'} ${s.kind==='hero'?'opening':''}"><div class="chapter-label"><span>ACTO ${String(state.index+1).padStart(2,'0')}</span> ${esc(s.section)} <i>✦</i></div>${content}</article><div class="page-signature">HALLOWEEN / UMSA · LA PAZ / 29 OCT 2026</div><div class="folio">${String(state.index+1).padStart(2,'0')}<small> / 18</small></div>`;
window.dispatchEvent(new CustomEvent('slidechange',{detail:{index:state.index,kind:s.kind,wide}}))}

function tickUI(){const s=slides[state.index];$('#play').textContent=state.running?'Pausar':'Iniciar / continuar';$('#auto').classList.toggle('active',state.auto);$('#time').textContent=`${clock(state.total)} / 30:00`;if(notes){$('#automatic').checked=state.auto;$('#connection').textContent=Date.now()-lastSeen<2500?'● Conectado al servidor · control compartido':'Reconectando con el servidor…';$('#clocks').innerHTML=`<small>ESTA DIAPOSITIVA / PREVISTO</small><span class="${state.elapsed>s.seconds*1000?'late':''}">${clock(state.elapsed)} / ${clock(s.seconds*1000)}</span><small>TOTAL / PREVISTO</small>${clock(state.total)} / 30:00`}}
function applyState(next){if(next.stamp<state.stamp&&lastSeen)return;const changed=state.index!==next.index;state=next;lastSeen=Date.now();if(changed){render();if(notes)window.scrollTo(0,0)}tickUI()}
async function command(type,index){try{const r=await fetch('/api/command',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({type,index})});if(!r.ok)throw Error();applyState(await r.json())}catch{lastSeen=0;tickUI()}}
async function sync(){try{const r=await fetch('/api/state',{cache:'no-store'});if(!r.ok)throw Error();applyState(await r.json())}catch{lastSeen=0;tickUI()}finally{setTimeout(sync,250)}}
$('#notes').onclick=()=>window.open('?notes','stellar-notes');$('#prev').onclick=()=>command('prev');$('#next').onclick=()=>command('next');$('#play').onclick=()=>command('play');$('#auto').onclick=()=>command('auto');$('#reset').onclick=()=>command('reset');$('#automatic').onchange=()=>command('auto');$('#index').onclick=e=>{const b=e.target.closest('[data-go]');if(b)command('go',Number(b.dataset.go))};$('#full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch{}};
document.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;const k=e.key.toLowerCase(),m={arrowright:'next',pagedown:'next',arrowleft:'prev',pageup:'prev',' ':'play',a:'auto',t:'reset'};if(m[k]){e.preventDefault();command(m[k])}if(k==='p')$('#notes').click();if(k==='f')$('#full').click()});
if(notes){document.body.classList.add('notes-mode');$('#presenter').hidden=false;$('#notes').textContent='Diapositivas ↗';$('#notes').onclick=()=>window.open('./','stellar-deck');document.body.insertBefore(document.querySelector('footer'),document.querySelector('#presenter'));document.querySelector('#presenter details').remove()}
render();tickUI();sync();
